import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
public final class WireTestMain {
 static int checks;
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static byte[] encode(ClipboardWire.Snapshot s)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();ClipboardWire.write(b,s,null);return b.toByteArray();}
 static ClipboardWire.Snapshot decode(byte[] b,File root)throws Exception{return ClipboardWire.read(new ByteArrayInputStream(b),root,null);}
 static void bad(byte[] b,File root,String label)throws Exception{int before=root.list().length;boolean failed=false;try{decode(b,root);}catch(IOException e){failed=true;}check(failed,label);check(root.list().length==before,label+" cleanup");}
 static void num(OutputStream o,long n,int c)throws IOException{for(int i=0;i<c;i++)o.write((int)(n>>>(i*8))&255);}
 static void str(OutputStream o,String s)throws IOException{byte[] b=s.getBytes(StandardCharsets.UTF_8);num(o,b.length,4);o.write(b);}
 static byte[] raw(int kind,int count,String name,String mime,long length)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();num(b,kind,1);num(b,5,8);num(b,count,4);if(count==1){str(b,name);str(b,mime);num(b,length,8);b.write(java.security.MessageDigest.getInstance("SHA-256").digest(new byte[0]));}return b.toByteArray();}
 static ClipboardWire.Snapshot files(){ClipboardWire.Snapshot s=new ClipboardWire.Snapshot();s.kind=3;s.id=123;ClipboardWire.Item f=new ClipboardWire.Item();f.name="marked-文件.bin";f.mime="application/octet-stream";f.length=150003;f.open=()->{byte[] b=new byte[150003];for(int i=0;i<b.length;i++)b[i]=(byte)(i*31);return new ByteArrayInputStream(b);};s.items.add(f);return s;}
 static void self(File root)throws Exception{
  ClipboardWire.Snapshot s=ClipboardWire.text("中文\nhello 😀");s.id=17;byte[] b=encode(s);ClipboardWire.Snapshot r=decode(b,root);check(ClipboardWire.textContent(r).equals("中文\nhello 😀"),"unicode");check(r.id==17,"id");check(s.fingerprint().equals(r.fingerprint()),"text fingerprint");
  ClipboardWire.Snapshot f=files();byte[] fb=encode(f);ClipboardWire.Snapshot fr=decode(fb,root);check(fr.items.get(0).length==150003,"file length");check(fr.items.get(0).file.exists(),"committed file");check(!fr.items.get(0).file.getPath().contains(".partial"),"atomic completion");check(f.fingerprint().equals(fr.fingerprint()),"file fingerprint");
  ClipboardWire.Snapshot du=files();du.items.add(files().items.get(0));ClipboardWire.Snapshot dr=decode(encode(du),root);check(dr.items.get(0).name.equals(dr.items.get(1).name)&&!dr.items.get(0).file.equals(dr.items.get(1).file),"duplicate basenames isolated");
  ClipboardWire.Snapshot im=files();im.kind=2;im.items.get(0).name="image.png";im.items.get(0).mime="image/png";check(decode(encode(im),root).kind==2,"image");
  byte[] corrupt=fb.clone();corrupt[corrupt.length-1]^=1;bad(corrupt,root,"digest mismatch");bad(Arrays.copyOf(fb,fb.length-2),root,"truncated");
  for(String n:new String[]{"../evil","a/b","a\\b","C:evil","CON","nul.txt","LPT1.txt","a.","a ","..","a\u0001","a\u0085"})bad(raw(3,1,n,"x",0),root,"unsafe "+n);
  bad(raw(9,0,"","",0),root,"kind");bad(raw(3,129,"","",0),root,"count");bad(raw(1,0,"","",0),root,"text count");bad(raw(3,1,"ok","x",1073741825L),root,"file limit");bad(raw(1,1,"text.txt","text/plain",1048577),root,"text limit");byte[] invalid=raw(3,1,"a","x",0);invalid[17]=(byte)255;bad(invalid,root,"invalid UTF8");byte[] meta=raw(3,1,"a","x",0);meta[13]=1;meta[14]=16;bad(meta,root,"metadata limit");
  final int[] calls={0};boolean canceled=false;int before=root.list().length;try{ClipboardWire.read(new ByteArrayInputStream(fb),root,()->++calls[0]>=3);}catch(InterruptedIOException e){canceled=true;}check(canceled,"read cancel");check(root.list().length==before,"cancel cleanup");calls[0]=0;canceled=false;try{ClipboardWire.write(new ByteArrayOutputStream(),files(),()->++calls[0]>=3);}catch(InterruptedIOException e){canceled=true;}check(canceled,"write cancel");
  ClipboardWire.Snapshot shortSource=files();shortSource.items.get(0).open=()->new ByteArrayInputStream(new byte[2]);boolean failed=false;try{encode(shortSource);}catch(IOException e){failed=true;}check(failed,"source shrunk");  ClipboardWire.Snapshot invalidText=ClipboardWire.text("x");invalidText.items.get(0).open=()->new ByteArrayInputStream(new byte[]{(byte)255});bad(encode(invalidText),root,"invalid text UTF8");byte[] overflow=raw(3,1,"ok","x",0);overflow[8]=(byte)128;bad(overflow,root,"u64 overflow");
  ClipboardWire.Snapshot excessive=files();excessive.items.get(0).length=1073741824L;ClipboardWire.Item e2=new ClipboardWire.Item();e2.name="b";e2.mime="x";e2.length=1073741824L;e2.open=()->{throw new AssertionError("source opened before validation");};excessive.items.add(e2);ClipboardWire.Item e3=new ClipboardWire.Item();e3.name="c";e3.mime="x";e3.length=1;e3.open=e2.open;excessive.items.add(e3);boolean limited=false;try{encode(excessive);}catch(IOException e){limited=true;}check(limited,"total limit before sources");
  final boolean[] bounded={true};ClipboardWire.Snapshot streamed=files();streamed.items.get(0).open=()->new ByteArrayInputStream(new byte[150003]){public synchronized int read(byte[] b,int o,int n){if(n>65536)bounded[0]=false;return super.read(b,o,n);}};byte[] streamedBytes=encode(streamed);check(bounded[0],"outbound bounded chunks");bounded[0]=true;ClipboardWire.read(new ByteArrayInputStream(streamedBytes){public synchronized int read(byte[] b,int o,int n){if(n>65536)bounded[0]=false;return super.read(b,o,n);}},root,null);check(bounded[0],"inbound bounded chunks");ClipboardWire.Snapshot cached=decode(fb,root);cached.items.get(0).file.delete();check(cached.fingerprint().equals(f.fingerprint()),"received fingerprint cached");boolean badString=false;try{ClipboardWire.text("\ud800");}catch(IOException e){badString=true;}check(badString,"invalid local surrogate");System.out.println("Java wire: "+checks+" assertions passed");
 }
 public static void main(String[] args)throws Exception{File out=new File(args[1]);File root=new File(out,"java-cache");root.mkdirs();if(args[0].equals("self"))self(root);else if(args[0].equals("write")){Files.write(new File(out,"java-text.bin").toPath(),encode(ClipboardWire.text("中文\nhello 😀")));Files.write(new File(out,"java-files.bin").toPath(),encode(files()));}else if(args[0].equals("verify")){check(ClipboardWire.textContent(decode(Files.readAllBytes(new File(out,"cs-text.bin").toPath()),root)).equals("中文\nhello 😀"),"C# text");ClipboardWire.Snapshot f=decode(Files.readAllBytes(new File(out,"cs-files.bin").toPath()),root);check(f.items.get(0).name.equals("marked-文件.bin"),"C# name");check(f.fingerprint().equals(files().fingerprint()),"C# fingerprint");System.out.println("C# -> Java fixtures passed");}}
}
